from lib import *
R = J('z87'); rp = R['ramp']; au = R['auto']
def S(k): return [x for x in out('z87').split('== ')[k].splitlines()[1:] if x.strip()]
r = {x['p']: x for x in rp}
steps = [
    step(f"200 个实例各自按「实例号 MD5 % 100 < percent」决定用不用新版本,percent 存在一个配置节点里。放量 5% → 20% → 50% → 100%:实际用新版本的实例数是 {r[5]['n']}、{r[20]['n']}、{r[50]['n']}、{r[100]['n']}(目标 10、40、100、200),所有实例看到配置变化并切换在 {r[5]['ms']:.0f}–{r[100]['ms']:.0f} ms 内完成。实际比例与目标有偏差,是因为 200 个实例的哈希分桶并不均匀;实例少时偏差更大。", t=tl(S(1)), done=[0], b=bars([[f"{x['p']}%", x['n'], f"{x['n']} / 200"] for x in rp[1:]], 200, done=[0, 1, 2, 3]), kv=KV([['放量阶梯', '5 → 20 → 50 → 100%'], ['切换耗时', f"{r[5]['ms']:.0f}–{r[100]['ms']:.0f} ms"]], ['放量阶梯'])),
    step(f"放量是单调的:5% 时的实例,在 20% 时仍在新版本里,依此类推(验证为 {R['mono']})—— 因为桶号由实例号固定下来,不会随机变。同一批用户不会在放量过程中来回在新旧版本间跳。", t=tl(S(1)), mark=[len(S(1)) - 1], kv=KV([['集合包含', '5% ⊂ 20% ⊂ 50% ⊂ 100%']], ['集合包含'])),
    step(f"一键回滚:percent 设回 0,最后一个实例切回旧版本发生在 {R['rollback_ms']:.0f} ms 内;没有实例遗留在新版本。", t=tl(S(2)), done=[0], kv=KV([['回滚到 0%', f"{R['rollback_ms']:.0f} ms"]], ['回滚到 0%'])),
    step("指定实例灰度:给 3 个内部测试实例建 /gray/override/<id> 节点,percent 仍是 0:恰好这 3 个切到新版本;删除节点后它们切回。白名单与百分比可以同时生效。", t=tl(S(3)), done=[0, 1], kv=KV([['白名单', 'inst-003、077、150'], ['percent', '仍为 0']], ['白名单'])),
    step(f"自动回滚:放量到 20%(38 个实例),其中 8 个出错并在 /gray/errors 下建临时节点;控制者 watch 该目录,看到 {au['errs']} 个(阈值 5)时把 percent 写回 0;从第一个错误上报到所有实例回到旧版本共 {au['ms']:.0f} ms,遗留 {au['left']} 个。注意:发现的是「错误上报」,不是真正的错误率 —— 真实的健康判断要更谨慎(窗口、比例)。", t=tl(S(4)), mark=[1], b=bars([['错误上报 → 全部回滚', au['ms'], f"{au['ms']:.0f} ms"]], 200, done=[0]), kv=KV([['自动回滚', f"{au['ms']:.0f} ms"], ['触发阈值', '5 个错误实例']], ['自动回滚'])),
]
A = dict(
    n=87, series='zookeeper', tags='ZooKeeper,灰度发布,配置,真实验证,动画演示',
    desc=f'用 ZooKeeper 配置节点做灰度发布:200 个实例按哈希分桶放量(5/20/50/100% → {r[5]["n"]}/{r[20]["n"]}/{r[50]["n"]}/{r[100]["n"]} 个),{r[100]["ms"]:.0f} ms 内全部切换、单调包含;回滚 {R["rollback_ms"]:.0f} ms;白名单实例灰度;错误上报触发自动回滚 {au["ms"]:.0f} ms。',
    lead='灰度发布的难点不在「推送新配置」,而在「只让一部分实例用新版本、并且随时能撤」。这篇用 200 个实例做按比例放量、按实例白名单、一键回滚和错误触发的自动回滚,每一步量实际生效的实例数与耗时。',
    facts=[(f'{r[5]["n"]}/{r[20]["n"]}/{r[50]["n"]}', '放量 5% / 20% / 50% 时实际切到新版本的实例数(共 200)'), (f'{R["rollback_ms"]:.0f} ms', '回滚到 0% 时全部实例切回旧版本'), (f'{au["ms"]:.0f} ms', '错误上报到自动回滚完成')],
    body=[
        sec('按比例放量', '', term('', blk('z87', 1)), '<p>灰度判断在<em>客户端</em>(实例自己)做:服务端只存一个 percent 数字,所有实例用同一个哈希函数算自己的桶。这样配置中心几乎没有压力,但意味着每个客户端都要带这段逻辑。推送机制见<a href="zookeeper-config-center.html">配置中心</a>。</p>'),
        sec('单调放量', '', '<p>用哈希而不是随机数,放量才是单调的。如果每次放量都重新随机,就会有实例在新旧版本间来回切换。</p>'),
        sec('回滚', '', term('', blk('z87', 2)), '<p>回滚就是把 percent 写回 0。因为所有实例都在 watch 同一个节点,所以回滚和放量一样快。</p>'),
        sec('指定实例', '', term('', blk('z87', 3))),
        sec('错误触发的自动回滚', '', term('', blk('z87', 4)), '<p>实例上报错误用的是<a href="zookeeper-ephemeral-persistent.html">临时节点</a>:实例死亡、会话过期后错误记录会自己消失。这里的阈值逻辑非常简化。</p>'),
        sec('分步演示', '', demo('灰度发布', [('t', 'term', '输出'), ('b', 'bars', '实例数 / 耗时'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_Z + '。200 个「实例」是同一进程里的 200 个 kazoo 连接(不是 200 个进程);版本切换只是内存里的一个布尔值,没有真正的新旧版本代码', '没有验证:真实业务流量下的错误率判断、按用户而非按实例灰度、服务端按比例下发(客户端不带逻辑)的方案、上千实例时的收敛时间'],
)
